"""navera_lite/ros/runner.py — start one node, spin it until Ctrl+C, and stop it cleanly. Part of NAVERA Lite,
the course's teaching stack (given in mission 09). Written for the course; it is not NAVERA code.

Every NAVERA Lite node's main() calls run_node(). Ctrl+C in a terminal (or `ros2 launch` stopping) often
sends SIGINT twice: once to the node and once more through launch. A second Ctrl+C during the clean-up
would kill the node with a KeyboardInterrupt traceback, and launch would report "process has died"; so
after the first one, further Ctrl+C are ignored while the node closes (a few milliseconds).
"""
import signal

import rclpy
from rclpy.executors import ExternalShutdownException


# from mission 09 — finished: read it, use it, do not change it
def run_node(node_class, args=None):
    """rclpy.init, node_class(), rclpy.spin until Ctrl+C, then destroy the node and shut rclpy down.

    Example: run_node(Replay)   (in replay_node.py's main)
    """
    rclpy.init(args=args)
    node = None
    try:
        node = node_class()
        rclpy.spin(node)
    except (KeyboardInterrupt, ExternalShutdownException):
        pass
    finally:
        signal.signal(signal.SIGINT, signal.SIG_IGN)          # a second Ctrl+C must not break the clean-up
        if node is not None:
            node.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()
